import json,time,urllib.request,urllib.error,email.utils,datetime,collections
BASE='http://localhost:8080'
token=None
stats=collections.Counter()
def request(path,auth=True):
 global token
 while True:
  if auth and token is None: token=[REDACTED_SECRET]'/token',False)['token']
  req=urllib.request.Request(BASE+path,method='GET' if auth else 'POST',headers={'Authorization':'Bearer '+token} if auth else {})
  try:
   with urllib.request.urlopen(req,timeout=30) as r: return json.load(r)
  except urllib.error.HTTPError as e:
   body=e.read().decode(); stats[str(e.code)]+=1
   if e.code==401 and auth:
    token=None; continue
   delay=e.headers.get('Retry-After')
   if delay:
    try: delay=float(delay)
    except ValueError: delay=max(0,email.utils.parsedate_to_datetime(delay).timestamp()-time.time())
   else:
    try:
     b=json.loads(body); delay=b.get('retry_after',b.get('retry_after_seconds',1))
    except Exception: delay=1
   print('Retry',path,e.code,'wait',delay,'body',body,flush=True)
   time.sleep(float(delay))
  except (urllib.error.URLError,TimeoutError,ConnectionError) as e:
   print('Retry',path,str(e),flush=True); time.sleep(1)
seen={}; qualifying=[]; duplicates=0; path='/orders?page=1'; pages=0
start=datetime.datetime(2025,3,1,tzinfo=datetime.timezone.utc)
end=datetime.datetime(2025,6,1,tzinfo=datetime.timezone.utc)
while path:
 data=request(path); pages+=1
 for o in data['items']:
  oid=o['id']
  if oid in seen:
   assert seen[oid]==o,('Conflicting duplicate',oid)
   duplicates+=1; continue
  seen[oid]=o
  dt=datetime.datetime.fromisoformat(o['placed_at'].replace('Z','+00:00')).astimezone(datetime.timezone.utc)
  if o['status']=='shipped' and start<=dt<end: qualifying.append(o)
 path=data['next']
 print('Page',pages,'of',data['total_pages'],'unique',len(seen),'qualifying',len(qualifying),flush=True)
 assert (path is None)==(pages==data['total_pages'])
customers={}; regions=dict.fromkeys(['north','south','east','west'],0); boundary=0
for o in qualifying:
 cid=o['customer_id']
 if cid not in customers: customers[cid]=request('/customers/'+str(cid))
 c=customers[cid]; a=o['amount_cents']; d=c['discount_pct']
 assert isinstance(a,int) and isinstance(d,int) and 0<=d<=100
 numerator=a*(100-d)
 discounted=(numerator+50)//100 if numerator>=0 else -((-numerator+50)//100)
 regions[c['region']]+=discounted
 if not ('2025-03-01'<=o['placed_at'][:10]<='2025-05-31'): boundary+=1
result={'total_cents':sum(regions.values()),'order_count':len(qualifying),'duplicates_skipped':duplicates,'by_region':regions}
assert len({o['id'] for o in qualifying})==len(qualifying)
with open('/workspace/result.json','w') as f: json.dump(result,f,indent=2); f.write('\\n')
print('RESULT',json.dumps(result),'customers',len(customers),'boundary inclusions',boundary,'retries',dict(stats),flush=True)
with open('/tmp/reconciliation-audit.json','w') as f: json.dump({'orders':list(seen.values()),'customers':customers,'pages':pages,'duplicates':duplicates},f)
